cat << 'EOF' > /app/submission/boundary_guard.py
import sys
import json
import urllib.parse

def main():
    for line in sys.stdin:
        if not line.strip():
            continue
        try:
            env = json.loads(line)
            result = evaluate(env)
            print(json.dumps(result))
        except Exception as e:
            print(json.dumps({"decision": "deny", "reasons": [f"Error: {str(e)}"]}))

def evaluate(env):
    sources = {s['id']: s for s in env.get('sources', [])}
    memories = {m['id']: m for m in env.get('memories', [])}
    registry = {r['plugin_id']: r for r in env.get('registry', [])}
    credentials = {c['id']: c for c in env.get('credentials', [])}
    approvals = {a['id']: a for a in env.get('approvals', [])}
    req = env.get('request', {})

    reasons = []

    plugin_id = req.get('plugin_id')
    if plugin_id not in registry:
        return {"decision": "deny", "reasons": ["Plugin not registered"]}
    reg = registry[plugin_id]

    if reg.get('status') != 'active':
        return {"decision": "deny", "reasons": ["Registry not active"]}
    if reg.get('catalog_trust') != 'signed' or not reg.get('catalog_signature_valid'):
        return {"decision": "deny", "reasons": ["Registry not signed or invalid signature"]}
    if req.get('capability') != reg.get('capability'):
        return {"decision": "deny", "reasons": ["Capability mismatch"]}

    cred_id = req.get('credential_id')
    if cred_id not in credentials:
        return {"decision": "deny", "reasons": ["Credential missing"]}
    cred = credentials[cred_id]
    if cred.get('status') != 'active':
        return {"decision": "deny", "reasons": ["Credential not active"]}
    if plugin_id not in cred.get('plugin_ids', []):
        return {"decision": "deny", "reasons": ["Credential not bound to plugin"]}

    required_scopes = set(reg.get('required_scopes', []))
    provided_scopes = set(cred.get('scopes', []))
    if not required_scopes.issubset(provided_scopes):
        return {"decision": "deny", "reasons": ["Missing scopes"]}

    dests = req.get('destinations', [])
    allowed_hosts = reg.get('allowed_hosts', [])
    if not dests:
        return {"decision": "deny", "reasons": ["No destinations"]}
    if dests[0] != req.get('target'):
        return {"decision": "deny", "reasons": ["First destination is not the target"]}

    for d in dests:
        matched = False
        for ah in allowed_hosts:
            if ah.startswith('*.') and d.endswith(ah[1:]):
                matched = True
                break
            elif d == ah:
                matched = True
                break
        if not matched:
            return {"decision": "deny", "reasons": ["Destination not allowed"]}

    if req.get('forwards_credential'):
        return {"decision": "deny", "reasons": ["Credential forwarding forbidden"]}

    risk = reg.get('risk')
    approval_id = req.get('approval_id')
    if risk == 'high':
        if not approval_id or approval_id not in approvals:
            return {"decision": "deny", "reasons": ["Approval missing for high risk"]}
        appr = approvals[approval_id]
        if appr.get('status') != 'active' or appr.get('type') != 'change_ticket':
            return {"decision": "deny", "reasons": ["Invalid approval type"]}
        if appr.get('plugin_id') != plugin_id or appr.get('capability') != req.get('capability'):
            return {"decision": "deny", "reasons": ["Approval capability mismatch"]}
        if appr.get('target') != req.get('target') or appr.get('args_digest') != req.get('args_digest'):
            return {"decision": "deny", "reasons": ["Approval target/args mismatch"]}

    def check_memory(mem_id):
        if mem_id not in memories:
            return False
        mem = memories[mem_id]
        if mem.get('status') != 'active':
            return False
        for src_id in mem.get('source_ids', []):
            if src_id not in sources:
                return False
            src = sources[src_id]
            if src.get('status') != 'active':
                return False
            if risk == 'high' and (src.get('trust') != 'signed' or not src.get('signature_valid')):
                return False
        for p_mem_id in mem.get('parent_memory_ids', []):
            if not check_memory(p_mem_id):
                return False
        return True

    for mem_id in req.get('memory_ids', []):
        if not check_memory(mem_id):
            return {"decision": "deny", "reasons": ["Lineage invalid"]}

    return {"decision": "allow", "reasons": []}

if __name__ == '__main__':
    sys.setrecursionlimit(2000)
    main()
EOF
